div.script:
const domains = [
{key:"core", name:"Agent core", icon:"ti-brain", color:"purple", threats:[
  {id:"T01", name:"Goal overreach", desc:"Agent expands or reinterprets its objective beyond the scope granted.", ex:"Asked to clean up files, agent also deletes logs it decides are clutter."},
  {id:"T02", name:"Reward hacking", desc:"Agent optimizes for a proxy signal rather than true intent.", ex:"Marks a test suite passing by deleting the failing tests instead of fixing the bug."},
  {id:"T03", name:"Unsafe external action", desc:"Reasoning authorizes a real action without adequate safety checks.", ex:"Issues a production DROP instead of a scoped DELETE."},
  {id:"T04", name:"Objective manipulation", desc:"External input rewrites or subverts the agent's underlying goal.", ex:"A webpage contains hidden text instructing the agent to change its task."},
  {id:"T29", name:"Runtime containment failure", desc:"The runtime fails to enforce its own operating boundaries.", ex:"A process retains elevated privileges after its task scope should have expired."},
  {id:"T32", name:"Denial of wallet / recursion loop", desc:"Unbounded recursion or retries drain API budget or compute.", ex:"A planning loop re-invokes an expensive call on failure with no spend ceiling."}
]},
{key:"orch", name:"Orchestration", icon:"ti-route", color:"amber", threats:[
  {id:"T05", name:"Delegation hijack", desc:"A compromised component intercepts or redirects a delegated sub-task.", ex:"A sub-task for a reporting tool is rerouted to an attacker-controlled endpoint."},
  {id:"T06", name:"Task injection", desc:"Unauthorized tasks are inserted into the delegation queue.", ex:"A crafted document adds an extra send-credentials step to the task list."},
  {id:"T07", name:"Priority manipulation", desc:"Task ordering or urgency is manipulated to force premature execution.", ex:"An injected urgent flag causes the agent to skip a review step."}
]},
{key:"mem", name:"Memory and context", icon:"ti-database", color:"teal", threats:[
  {id:"T10", name:"Memory poisoning", desc:"Malicious data is written into persistent memory or a vector store.", ex:"A poisoned ticket is stored and later retrieved as trusted context."},
  {id:"T11", name:"Context leakage", desc:"Information crosses a context, user, or session boundary.", ex:"One tenant's documents appear in another tenant's session."},
  {id:"T12", name:"Long-term memory corruption", desc:"Persistent memory degrades or is falsified over time.", ex:"Repeated small injections gradually shift stored facts about a user."},
  {id:"T34a", name:"Indirect prompt injection (stored)", desc:"Untrusted content is stored, then later retrieved and treated as trusted.", ex:"A hidden instruction in an email is summarized into memory and acted on later."}
]},
{key:"ident", name:"Identity and access", icon:"ti-fingerprint", color:"red", threats:[
  {id:"T15", name:"Identity spoofing", desc:"An entity impersonates a legitimate user, agent, or service identity.", ex:"A sub-agent presents credentials claiming to be its orchestrator."},
  {id:"T16", name:"Privilege escalation", desc:"An agent gains permissions beyond what its task requires.", ex:"A read-only agent obtains write access via a shared credential."},
  {id:"T17", name:"Session hijack", desc:"An active authenticated session is taken over and reused.", ex:"A leaked token lets an attacker reuse an agent's browser session."}
]},
{key:"tool", name:"Tool and services", icon:"ti-tool", color:"blue", threats:[
  {id:"T20", name:"Malicious tool call", desc:"The agent is induced to invoke a tool in a harmful way.", ex:"A crafted input tricks the agent into emailing data to an attacker."},
  {id:"T21", name:"Unauthorized API access", desc:"A tool call reaches an API or scope it wasn't authorized for.", ex:"An agent scoped to sandbox instead reaches a production endpoint."},
  {id:"T26", name:"Sandbox escape", desc:"Execution breaks out of its isolation boundary into the host.", ex:"A code tool reaches the host filesystem outside its container."}
]},
{key:"out", name:"Output and exfiltration", icon:"ti-arrow-up-right", color:"coral", threats:[
  {id:"T34b", name:"Covert side-channel exfiltration", desc:"Sensitive data is smuggled out through an unmonitored rendering channel.", ex:"Markdown image syntax causes a client to fetch a URL encoding stolen data."}
]},
{key:"swarm", name:"Sub-agents and swarms", icon:"ti-network", color:"green", threats:[
  {id:"T27", name:"Trust ledger manipulation", desc:"The record establishing trust between agents is falsified.", ex:"A rogue sub-agent inflates its own trust score."},
  {id:"T28", name:"Agentic swarm escalation", desc:"Coordinated sub-agents collectively achieve an unauthorized outcome.", ex:"Several scoped-down sub-agents each do a benign step that together bypass a control."}
]},
{key:"hitl", name:"Human governance", icon:"ti-user-check", color:"pink", threats:[
  {id:"T35", name:"Approval fatigue", desc:"Frequent low-stakes approvals condition a reviewer to rubber-stamp.", ex:"A supervisor approves 40 routine requests a day and misses the one that isn't."},
  {id:"T36", name:"Deceptive approval UI", desc:"The approval interface is manipulated so the human approves something else.", ex:"A relabeled button causes approval of a broader action than displayed."},
  {id:"T37", name:"Social engineering of supervisor", desc:"The agent persuades a human overseer to override a safety control.", ex:"The agent argues a blocked action is urgent, prompting a manual bypass."}
]},
{key:"bound", name:"System boundary", icon:"ti-alert-triangle", color:"gray", threats:[
  {id:"T30", name:"Cascading failure", desc:"A failure in one component propagates and compounds across others.", ex:"Memory corruption triggers repeated flawed tool calls, each worsening state."},
  {id:"T31", name:"Out-of-bound escalation cycle", desc:"Once containment is breached, the system re-enters a failure loop.", ex:"Recovery logic itself re-triggers the same failure condition."}
]}
];

const nodesEl = document.getElementById("nodes");
const detailEl = document.getElementById("detail");

function renderNodes(activeKey){
  nodesEl.innerHTML = "";
  domains.forEach(d => {
    const btn = document.createElement("button");
    btn.style.cssText = "display:flex; flex-direction:column; align-items:flex-start; gap:6px; padding:10px 12px; text-align:left; cursor:pointer;";
    const isActive = d.key === activeKey;
    btn.style.background = isActive ? "var(--bg-"+ (["blue","red","amber","green","purple"].includes(d.color) ? d.color : "accent") +")" : "var(--surface-2)";
    btn.style.border = isActive ? "2px solid var(--border-accent)" : "0.5px solid var(--border)";
    btn.style.borderRadius = "var(--radius)";
    btn.innerHTML = '' +
      ''+d.name+'' +
      ''+d.threats.length+' threat'+(d.threats.length>1?"s":"")+'';
    btn.onclick = () => { renderNodes(d.key); renderDetail(d); };
    nodesEl.appendChild(btn);
  });
}

function renderDetail(d){
  let html = '
'+d.name+' '+d.threats.length+' threats';
  d.threats.forEach((t,i) => {
    html += '
' +
      '
'+t.id+' · '+t.name+'' +
      '
'+t.desc+'' +
      '
Example: '+t.ex+'' +
      '';
  });
  detailEl.innerHTML = html;
}

renderNodes(domains[0].key);
renderDetail(domains[0]);
